-- mod-subclass: helmet displays that cover a Two-Headed Ogre mouth (1 left head, 2 right head).

DROP TABLE IF EXISTS `mod_subclass_mouth_cover`;
CREATE TABLE `mod_subclass_mouth_cover` (
    `DisplayId` INT UNSIGNED NOT NULL,
    `Heads` TINYINT UNSIGNED NOT NULL,
    PRIMARY KEY (`DisplayId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 233 AND 34850;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 34851 AND 43291;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 43316 AND 53139;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 53141 AND 64774;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 64782 AND 131380;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 131381 AND 145829;
DELETE FROM `mod_subclass_mouth_cover` WHERE `DisplayId` BETWEEN 145832 AND 170239;
